Q: How to do hierarchical queries with arrays A: <p>Meanwhile found a solution which is very close to the database functions I have mentioned.</p>
<pre><code>function connectBy(array, startWith, connectWith, path = [], level = 0) {
   const filterFn = typeof startWith == 'function' ?
      startWith :
      function (x) {
         const children = startWith[startWith.length - 1][connectWith[1]];
         return Array.isArray(children) ? children.includes(x[connectWith[0]]) : children == x[connectWith[0]];
      };
   for (let item of array.filter(filterFn)) {
      if (path.includes(array.indexOf(item)))
         item.isCycle = true;    
      item.level = level;
      item.path = path.concat(array.indexOf(item));
      typeof startWith == 'function' ? startWith = [item] : startWith.push(item);
      if (!item.isCycle)
         startWith = connectBy(array, startWith, connectWith, item.path, level + 1);
   }
   return startWith;
}
</code></pre>
<p>The <code>startWith</code> parameter is a function to get the top-level items. <code>connectWith</code> is an array of two strings to define the fields for joining.</p>
<pre><code>const myArray = [
   { name: 'Alice', children: ['Bob', 'Bill'] },
   { name: 'Bob', children: 'Cindy' },
   { name: 'Bill', children: [] },
   { name: 'Cindy', children: ['David', 'Don'] },
   { name: 'David',children: ['Bob'] },
   { name: 'Don' },
];
const arr = connectBy(
   myArray, 
   function (val) { return val.name == 'Alice'}, 
   ['name', 'children']
);

[
  { name: 'Alice', children: [ 'Bob', 'Bill' ], level: 0, path: [ 0 ] },
  {
    name: 'Bob',
    children: 'Cindy',
    level: 4,
    path: [ 0, 1, 3, 4, 1 ],
    isCycle: true
  },
  {
    name: 'Cindy',
    children: [ 'David', 'Don' ],
    level: 2,
    path: [ 0, 1, 3 ]
  },
  {
    name: 'David',
    children: [ 'Bob' ],
    level: 3,
    path: [ 0, 1, 3, 4 ]
  },
  {
    name: 'Bob',
    children: 'Cindy',
    level: 4,
    path: [ 0, 1, 3, 4, 1 ],
    isCycle: true
  },
  { name: 'Don', level: 3, path: [ 0, 1, 3, 5 ] },
  { name: 'Bill', children: [], level: 1, path: [ 0, 2 ] }
]
</code></pre>
<p>With added <code>path</code> and <code>level</code> information it is very simple to generate the output or make other transformations.</p>
<pre><code>arr = connectBy(myArray, function (val) { return val.name == 'Alice'}, ['name', 'children']);

console.log(arr.map(x =&gt; ' '.repeat(2 * x.level) + x.name).join('\n'))

Alice
  Bob
    Cindy
      David
      Don
  Bill


console.log(arr.map(x =&gt; x.path.map(m =&gt; myArray[m].name).join(' -&gt; ')).join('\n'))

Alice
Alice -&gt; Bob
Alice -&gt; Bob -&gt; Cindy
Alice -&gt; Bob -&gt; Cindy -&gt; David
Alice -&gt; Bob -&gt; Cindy -&gt; Don
Alice -&gt; Bill
</code></pre>
<p>It also works the other way around</p>
<pre><code>myArray = [
   { name: 'Alice' },
   { name: 'Bob', parent: 'Alice' },
   { name: 'Bill', parent: 'Alice' },
   { name: 'Cindy', parent: 'Bob' },
   { name: 'David', parent: 'Cindy' },
   { name: 'Don', parent: 'Cindy' }
]
arr = connectBy(myArray, (val) =&gt; { return val.parent == null }, ['parent', 'name']);
</code></pre>
<p>Or with One-to-Many relations:</p>
<pre><code>myArray = [
   { name: 'Adam', children: ['Britney'] },
   { name: 'Alice', children: ['Britney'] },
   { name: 'Britney' }
]

arr = connectBy(myArray, (x) =&gt; { return x.children != null }, ['name', 'children']);
console.log(arr.map(x =&gt; ' '.repeat(2 * x.level) + x.name).join('\n'))

Adam
  Britney
Alice
  Britney
</code></pre>
